DATABASE_URL=postgres://dev:dev-password@localhost:5432/devdb
AWS_ACCESS_KEY_ID=dev-key
AWS_SECRET_ACCESS_KEY=dev-secret
# Use local DynamoDB or other sandboxed services
```

```bash
