PORT=8080
# Database and service connections via private network
```

### 4. Production Secret Management Strategy

In production, use one of these approaches instead of .env files:

```javascript
// Option 1: Use AWS Systems Manager Parameter Store (if on AWS)
const AWS = require('aws-sdk');
const ssm = new AWS.SSM();

async function getSecret(name) {
  const params = {
    Name: name,
    WithDecryption: true
  };

  const result = await ssm.getParameter(params).promise();
  return result.Parameter.Value;
}

// Option 2: Use environment variables from deployment platform
// (Heroku, Kubernetes, etc.)
function getSecret(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Required secret not found: ${name}`);
  }
  return value;
}
```

### 5. Enhanced .gitignore

```gitignore
# Environment variables
.env
.env.local
.env.development.local
.env.test.local
.env.production.local

# Secrets
secrets/**
credentials.json
*.pem
*.key
*.crt

# Node
node_modules/
